import sys
import time

class MarriageFunction:
    _total_time = 0.0

    @classmethod
    def do_task(cls, task):
        name, duration = task
        duration = max(int(duration), 0)
        start = time.time()
        time.sleep(duration)
        end = time.time()
        elapsed = round(end - start, 2)
        cls._total_time += elapsed
        print(f"{name} took {elapsed} seconds")

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    idx = 0
    n = len(data)
    while idx < n and data[idx] not in '([{(\'":':
        idx += 1
    while idx < n and data[idx] in '([{(\'":':
        idx += 1
    while idx < n and data[idx] in ' \t\n\r':
        idx += 1
    tasks = []
    while idx < n:
        while idx < n and data[idx] in ' \t\n\r':
            idx += 1
        if idx >= n:
            break
        if data[idx] == '(':
            idx += 1
            while idx < n and data[idx] in ' \t\n\r':
                idx += 1
            task_name = ""
            while idx < n and data[idx] not in ',)':
                if data[idx] not in ' \t\n\r':
                    task_name += data[idx]
                idx += 1
            while idx < n and data[idx] in ' \t\n\r':
                idx += 1
            if idx < n and data[idx] == ',':
                idx += 1
            while idx < n and data[idx] in ' \t\n\r':
                idx += 1
            duration_str = ""
            while idx < n and data[idx] not in ')':
                if data[idx] not in ' \t\n\r':
                    duration_str += data[idx]
                idx += 1
            if idx < n and data[idx] == ')':
                idx += 1
            if task_name and duration_str:
                tasks.append((task_name, int(duration_str)))
        idx += 1
    for task in tasks:
        MarriageFunction.do_task(task)

if __name__ == "__main__":
    main()
